function ForgeTuyereBrushMaker.init() ForgeTuyereBrushMaker.ironStock=10; ForgeTuyereBrushMaker.bronzeStock=8; ForgeTuyereBrushMaker.woodStock=14; ForgeTuyereBrushMaker.leatherStock=14; ForgeTuyereBrushMaker.silverStock=8; ForgeTuyereBrushMaker.goldStock=6; ForgeTuyereBrushMaker.jewelStock=4; ForgeTuyereBrushMaker.pearlStock=4; ForgeTuyereBrushMaker.productStock={}; ForgeTuyereBrushMaker.buildings={}; ForgeTuyereBrushMaker.maker=nil; ForgeTuyereBrushMaker.activeMaking={}; ForgeTuyereBrushMaker.totalProducts=0; ForgeTuyereBrushMaker.dayTimer=0; print("[ForgeTuyereBrushMaker] Royal Forge Tuyere Brush Maker System initialized (6 products, 4 buildings)") end
function ForgeTuyereBrushMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeTuyereBrushMaker.maker={name=n or ("Ščetkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščetkar najet: %s (spretnost: %d)",ForgeTuyereBrushMaker.maker.name,s),"success") end; return true end
function ForgeTuyereBrushMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeTuyereBrushMaker.build(id) local ok,e=ForgeTuyereBrushMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeTuyereBrushMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeTuyereBrushMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeTuyereBrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeTuyereBrushMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeTuyereBrushMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeTuyereBrushMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeTuyereBrushMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeTuyereBrushMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeTuyereBrushMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeTuyereBrushMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeTuyereBrushMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeTuyereBrushMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeTuyereBrushMaker.buildings==0 then return false,"Potrebna scetna delavnica" end; if not ForgeTuyereBrushMaker.maker then return false,"Potreben scetkar" end; return true end
function ForgeTuyereBrushMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeTuyereBrushMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeTuyereBrushMaker.ironStock=ForgeTuyereBrushMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeTuyereBrushMaker.bronzeStock=ForgeTuyereBrushMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeTuyereBrushMaker.woodStock=ForgeTuyereBrushMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeTuyereBrushMaker.leatherStock=ForgeTuyereBrushMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeTuyereBrushMaker.silverStock=ForgeTuyereBrushMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeTuyereBrushMaker.goldStock=ForgeTuyereBrushMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeTuyereBrushMaker.jewelStock=ForgeTuyereBrushMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeTuyereBrushMaker.pearlStock=ForgeTuyereBrushMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeTuyereBrushMaker.maker then t=math.max(1,t-math.floor(ForgeTuyereBrushMaker.maker.skill/13)) end; table.insert(ForgeTuyereBrushMaker.activeMaking,{id="forgetuyerebrush_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeTuyereBrushMaker.completeMaking(m) local q=1.0+(ForgeTuyereBrushMaker.getQualityBonus()/100); if ForgeTuyereBrushMaker.maker then q=q+(ForgeTuyereBrushMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeTuyereBrushMaker.productStock[m.productType]=(ForgeTuyereBrushMaker.productStock[m.productType] or 0)+m.quantity; ForgeTuyereBrushMaker.totalProducts=ForgeTuyereBrushMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeTuyereBrushMaker.maker then ForgeTuyereBrushMaker.maker.itemsMade=ForgeTuyereBrushMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeTuyereBrushMaker.maker.skill=math.min(100,ForgeTuyereBrushMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščetka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgetuyerebrush.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeTuyereBrushMaker.update(dt) if not _G.state then return end; ForgeTuyereBrushMaker.dayTimer=ForgeTuyereBrushMaker.dayTimer+dt; if ForgeTuyereBrushMaker.dayTimer>=30 then ForgeTuyereBrushMaker.dayTimer=0; for i=#ForgeTuyereBrushMaker.activeMaking,1,-1 do local m=ForgeTuyereBrushMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeTuyereBrushMaker.completeMaking(m); table.remove(ForgeTuyereBrushMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeTuyereBrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeTuyereBrushMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeTuyereBrushMaker.getStats() return {ironStock=ForgeTuyereBrushMaker.ironStock,bronzeStock=ForgeTuyereBrushMaker.bronzeStock,woodStock=ForgeTuyereBrushMaker.woodStock,leatherStock=ForgeTuyereBrushMaker.leatherStock,silverStock=ForgeTuyereBrushMaker.silverStock,goldStock=ForgeTuyereBrushMaker.goldStock,jewelStock=ForgeTuyereBrushMaker.jewelStock,pearlStock=ForgeTuyereBrushMaker.pearlStock,productStock=ForgeTuyereBrushMaker.productStock,numBuildings=#ForgeTuyereBrushMaker.buildings,hasMaker=ForgeTuyereBrushMaker.maker~=nil,makerName=ForgeTuyereBrushMaker.maker and ForgeTuyereBrushMaker.maker.name or "—",makerSkill=ForgeTuyereBrushMaker.maker and ForgeTuyereBrushMaker.maker.skill or 0,activeMaking=#ForgeTuyereBrushMaker.activeMaking,totalProducts=ForgeTuyereBrushMaker.totalProducts} end
